<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Staff,Audit,Accounts,Notifications};
final class Tokens {
 public static function invite(\PDO $p,int $u,int $programme,int $staff):string {
  return Core::tx($p,function()use($p,$u,$programme,$staff){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'invitations.manage',$r);$s=Staff::get($p,$u,$staff);$c=Policy::config($p,$r,true);Registration::eligibility($p,$r,$c,Registration::snapshot($p,$staff));if(!$r['is_published']||$r['is_cancelled']||$c['end_at']<=gmdate('Y-m-d H:i:s'))throw new \RuntimeException('Program tidak dibuka.');Database::query($p,'UPDATE training_invitations SET revoked_at=UTC_TIMESTAMP() WHERE programme_id=? AND staff_identity_id=? AND used_at IS NULL AND revoked_at IS NULL',[$programme,$staff]);$token=bin2hex(random_bytes(32));$expiry=min($c['end_at'],gmdate('Y-m-d H:i:s',time()+7*86400));Database::query($p,'INSERT INTO training_invitations(programme_id,staff_identity_id,token_hash,issued_by,expires_at) VALUES(?,?,?,?,?)',[$programme,$staff,hash('sha256',$token),$u,$expiry]);$id=(int)$p->lastInsertId();$url=Accounts::origin().'/training/invite?token='.$token;$user=Database::query($p,'SELECT id FROM users WHERE staff_identity_id=? AND is_active=1',[$staff])->fetchColumn();if($user)Events::emit($p,$programme,(int)$user,'invite:'.$id,'Jemputan: '.$c['title'],['url'=>$url,'expires_at'=>$expiry]);elseif($s['official_email'])Notifications::enqueue($p,$s['official_email'],'training_invitation',['message'=>'Claim akaun melalui portal terlebih dahulu, kemudian buka jemputan: '.$c['title'],'url'=>$url,'expires_at'=>$expiry]);Audit::record($p,'programme.invited',$u,(int)$r['owner_organisation_id'],(string)$id,'training',null,null,['staff_identity_id'=>$staff]);return $url;});
 }
 public static function invitation(\PDO $p,int $u,int $programme,string $token,bool $lock=false):array {
  $a=Policy::actor($p,$u);if(!preg_match('/\A[a-f0-9]{64}\z/',$token))throw new \RuntimeException('Jemputan tidak sah.');$r=Database::query($p,'SELECT * FROM training_invitations WHERE token_hash=? AND programme_id=? AND staff_identity_id=? AND used_at IS NULL AND revoked_at IS NULL AND expires_at>UTC_TIMESTAMP()'.($lock?' FOR UPDATE':''),[hash('sha256',$token),$programme,$a['staff_identity_id']])->fetch();if(!$r)throw new \RuntimeException('Jemputan tidak sah/tamat tempoh.');return $r;
 }
 public static function link(\PDO $p,int $u,int $programme):string {
  return Core::tx($p,function()use($p,$u,$programme){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'links.manage',$r);if(!$r['is_published']||$r['is_cancelled'])throw new \RuntimeException('Terbitkan program dahulu.');Database::query($p,'UPDATE training_links SET revoked_at=UTC_TIMESTAMP() WHERE programme_id=? AND revoked_at IS NULL',[$programme]);$key=bin2hex(random_bytes(16));Database::query($p,'INSERT INTO training_links(programme_id,public_key,created_by) VALUES(?,?,?)',[$programme,$key,$u]);Audit::record($p,'programme.link_rotated',$u,(int)$r['owner_organisation_id'],(string)$programme,'training');return Accounts::origin().'/training/register?key='.$key;});
 }
 public static function resolve(\PDO $p,string $key,bool $lock=false):array {if(!preg_match('/\A[a-f0-9]{32}\z/',$key))throw new \RuntimeException('Pautan tidak tersedia.');$r=Database::query($p,'SELECT * FROM training_links WHERE public_key=? AND revoked_at IS NULL'.($lock?' FOR UPDATE':''),[$key])->fetch();if(!$r)throw new \RuntimeException('Pautan tidak tersedia.');Policy::published($p,(int)$r['programme_id']);return $r;}
 public static function revoke(\PDO $p,int $u,int $programme,int $invitation):void {Core::tx($p,function()use($p,$u,$programme,$invitation){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'invitations.manage',$r);$row=Database::query($p,'SELECT id FROM training_invitations WHERE id=? AND programme_id=?',[$invitation,$programme])->fetchColumn();if(!$row)throw new \RuntimeException('Jemputan tidak wujud.');Database::query($p,'UPDATE training_invitations SET revoked_at=UTC_TIMESTAMP() WHERE id=?',[$row]);Audit::record($p,'programme.invitation_revoked',$u,(int)$r['owner_organisation_id'],(string)$row,'training');});}
}
